export type SupplierProduct = typeof supplierProducts.$inferSelect
export type NewSupplierProduct = typeof supplierProducts.$inferInsert

/** Internal supplier orders — shop procurement, not customer-facing */
export const supplierOrders = sqliteTable('supplier_orders', {
  id: text('id').primaryKey(),
  supplierName: text('supplier_name').notNull(),
  status: text('status', { enum: ['pending', 'ordered', 'received'] }).notNull().default('pending'),
  referenceNumber: text('reference_number'),
  orderedAt: integer('ordered_at', { mode: 'timestamp' }),
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  statusIdx: index('supplier_orders_status_idx').on(table.status),
}))

export type SupplierOrder = typeof supplierOrders.$inferSelect
export type NewSupplierOrder = typeof supplierOrders.$inferInsert

/** Line items for supplier orders */
export const supplierOrderLines = sqliteTable('supplier_order_lines', {
  id: text('id').primaryKey(),
  orderId: text('order_id').notNull().references(() => supplierOrders.id),
  eanUpc: text('ean_upc').notNull(),
  partId: text('part_id').references(() => parts.id), // nullable until imported into local catalog
  quantityOrdered: integer('quantity_ordered', { mode: 'number' }).notNull().default(1),
  quantityReceived: integer('quantity_received', { mode: 'number' }).notNull().default(0),
}, (table) => ({
  orderIdIdx: index('supplier_order_lines_order_id_idx').on(table.orderId),
}))

export type SupplierOrderLine = typeof supplierOrderLines.$inferSelect
export type NewSupplierOrderLine = typeof supplierOrderLines.$inferInsert

